from taf.ul.ettf.sim.core.command import Command
from taf.ul.ettf.throughput.common_throughput import CommonThroughput
from taf.ul.ettf.throughput.parsers import ThroughputParser
from taf.ul.ettf.throughput.throughtput_command import ThroughputCommand
from taf.ul.ettf.throughput.validator import AssertThatThroughput, BasicValidator
from taf.ul.ettf.throughput.assertion_conditions import EqualsTo, Reaches
from taf.ul.ettf.sim.core.validators import Validators


class BearerThroughputCommand(ThroughputCommand):
    def __init__(self, ue_id, validators=Validators()):
        super(BearerThroughputCommand, self).__init__('bearer_stats ue={}'.format(ue_id), validators, ThroughputParser())
        self.add_param('size_unit', 'bytes')
        Command.command_elements.add_modulator('selection_type', 'Value')
        Command.command_elements.add_modulator('parameter', 'Average data rate')


class BearerCommandOptions(CommonThroughput):
    def with_group(self, group):
        self.append_command_attribute('_group_', group)

    def with_direction(self, direction):
        self.append_command_attribute('dir', direction)

    def with_pdu(self, pdu):
        self.append_command_attribute('pdu', pdu)

    def with_qfi(self, qfi):
        self.append_command_attribute('qfi', qfi)

    def with_trf_id(self, trf_id):
        self.append_command_attribute('trf_id', trf_id)

    def with_srb_id(self, srb_id):
        self.append_command_attribute('srb_id', srb_id)

    def with_corruption_stats(self):
        self.append_command_attribute('include_corruption_stats', 'on')

    def with_mcg_dc_cell_group(self):
        self.append_command_attribute('dc_cell_group', 'mcg')

    def with_scg_dc_cell_group(self):
        self.append_command_attribute('dc_cell_group', 'scg')
        self.with_display_average_rate()

    def with_all_dc_cell_group(self):
        self.append_command_attribute('dc_cell_group', 'all')
        self.with_display_average_rate()

    def with_display_average_rate(self):
        self.append_command_attribute('display_average_rate', 'on')


PARAMETERS_NAME_MAPPING = {
    'Maximum': 'Maximum data rate',
    'Minimum': 'Minimum data rate',
    'Average': 'Average data rate',
}


class BearerThroughputAssertions(CommonThroughput):
    def get_bearer_throughput(self, ue_id, parameter=None):
        mapped_param = PARAMETERS_NAME_MAPPING.get(parameter, parameter)
        validator = BasicValidator(parameter=mapped_param)
        return self.init_simple_command(BearerThroughputCommand(ue_id, Validators(validator)))

    def assert_that_bearer_throughput_equals(self, ue_id, expected_throughput, parameter=None, selection_type=None, margin=.0):
        mapped_param = PARAMETERS_NAME_MAPPING.get(parameter, parameter)
        validator = AssertThatThroughput(EqualsTo(expected_throughput), selection_type=selection_type, parameter=mapped_param, margin=margin)
        self.init_command(BearerThroughputCommand(ue_id, Validators(validator)))

    def assert_that_expected_bearer_throughput_is_reached(self, ue_id, expected_throughput, parameter=None, selection_type=None, margin=.0):
        mapped_param = PARAMETERS_NAME_MAPPING.get(parameter, parameter)
        validator = AssertThatThroughput(Reaches(expected_throughput), selection_type=selection_type, parameter=mapped_param, margin=margin)
        self.init_command(BearerThroughputCommand(ue_id, Validators(validator)))

    def assert_that_bearer_throughput(self, ue_id):
        self.start()
        self.init_command(BearerThroughputCommand(ue_id))


class BearerThroughput(BearerCommandOptions, BearerThroughputAssertions):
    pass


bearer = BearerThroughput
